import { existsSync } from 'node:fs';
import { inject } from 'vitest';

// End-to-end tests run against the local Docker stack configured by
// `pnpm bootstrap`; in CI the same file is generated by the bootstrap step.
if (existsSync('.env')) process.loadEnvFile('.env');
// ...but on the throwaway database of this run (test/global-setup.ts).
process.env.DATABASE_URL = inject('databaseUrl');
